import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    p = [int(x) for x in input[1:]]

    graph = defaultdict(list)
    for i in range(n):
        if p[i] != -1:
            graph[p[i] - 1].append(i)

    def dfs(node):
        if not graph[node]:
            return 1
        return 1 + max(dfs(child) for child in graph[node])

    max_depth = 0
    for i in range(n):
        if p[i] == -1:
            max_depth = max(max_depth, dfs(i))

    print(max_depth)

if __name__ == "__main__":
    main()
